import { kebabCase, keyBy } from 'es-toolkit';
import { toNumber } from 'es-toolkit/compat';

export interface Row { id: number; name: string; age: number; }
export type Config = Record<string, unknown>;

export function toSlug(label: string): string { return kebabCase(label); }
export function byNameKey(rows: Row[]): Record<string, Row> { return keyBy(rows, (row) => row.name); }
export function parseAmount(text: string): number { return toNumber(text); }
```

- **`toSlug`**: `kebabCase` from the `es-toolkit` root. Its word pattern splits on case changes, digit runs and separators the same way lodash does for this input set. I used the root export rather than `es-toolkit/compat`, because compat's version adds deburring.
- **`byNameKey`**: `keyBy` from `es-toolkit` with an arrow function in place of lodash's property shorthand. Both keep the last row for each name, and both return `{}` for an empty array. The signature is unchanged.
- **`parseAmount`**: `toNumber` from `es-toolkit/compat`, which is `Number()` plus a symbol check. For the allowed characters it matches lodash's `toNumber`. I chose it over a bare `Number(text)` because it is a library call. The bare version bundles to 305 bytes instead of 346, so it is the option to pick if the size gap matters more than the library rule.

